/**
 * Parquet (.parquet) Read-Only Viewing Tests for CSV ClearView
 *
 * Loads src/parquet.ts and reads the fixtures in tests/fixtures (generated by
 * tests/fixtures/make_parquet_fixtures.py), checking type coercion, every
 * compression codec, partial reads of large files, and errors.
 * Run with: node tests/parquet.test.js
 */

const fs = require('fs');
const path = require('path');
const Module = require('module');
const ts = require('typescript');

let passed = 0;
let failed = 0;
const failures = [];

function assert(condition, testName) {
    if (condition) {
        passed++;
        console.log(`  ✅ ${testName}`);
    } else {
        failed++;
        failures.push(testName);
        console.log(`  ❌ ${testName}`);
    }
}

function assertEqual(actual, expected, testName) {
    if (JSON.stringify(actual) === JSON.stringify(expected)) {
        passed++;
        console.log(`  ✅ ${testName}`);
    } else {
        failed++;
        failures.push(testName);
        console.log(`  ❌ ${testName}`);
        console.log(`     Expected: ${JSON.stringify(expected)}`);
        console.log(`     Actual:   ${JSON.stringify(actual)}`);
    }
}

const srcPath = path.join(__dirname, '..', 'src', 'parquet.ts');
const js = ts.transpileModule(fs.readFileSync(srcPath, 'utf8'), {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 }
}).outputText;
const mod = new Module(srcPath);
mod.paths = Module._nodeModulePaths(path.dirname(srcPath));
mod._compile(js, srcPath);
const { readParquet, parquetValueToString } = mod.exports;

const fixture = name => path.join(__dirname, 'fixtures', name);

// Mirrors csvEscapeField and the join in ensureParquetText (src/csvEditor.ts)
function csvEscapeField(value) {
    if (/[",\r\n]/.test(value)) {
        return `"${value.replace(/"/g, '""')}"`;
    }
    return value;
}
function tableToCsv(table) {
    return [table.header, ...table.rows].map(f => f.map(csvEscapeField).join(',')).join('\r\n') + '\r\n';
}

const EXPECTED_HEADER = ['id', 'big', 'price', 'flag', 'name', 'note', 'day', 'ts', 'blob', 'tags', 'pt', 'attrs'];
const EXPECTED_ROWS = [
    ['1', '9007199254740993', '1.5', 'true', 'plain', '', '2024-01-31T00:00:00.000Z', '2024-01-31T12:30:45.123Z', '<binary 3 bytes>', '[1,2]', '{"a":1,"b":"x"}', '{"k":1}'],
    ['2', '-1', '', 'false', 'has, comma', '', '', '', '', '[]', '', ''],
    ['3', '', '-0.25', '', 'say "hi"\nbye', 'x', '1970-01-01T00:00:00.000Z', '2000-01-01T00:00:00.000Z', 'ok', '', '{"a":2,"b":null}', '{}'],
];

async function runTests() {
    console.log('\n📋 Every column type (snappy and zstd)');
    for (const name of ['types.snappy.parquet', 'types.zstd.parquet']) {
        const t = await readParquet(fixture(name), 1e9);
        assertEqual(t.header, EXPECTED_HEADER, `${name}: header from schema`);
        assertEqual(t.rows, EXPECTED_ROWS, `${name}: rows coerced to text`);
        assertEqual(t.totalRows, 3, `${name}: totalRows from metadata`);
    }

    console.log('\n📋 CSV text');
    {
        const csv = tableToCsv(await readParquet(fixture('types.snappy.parquet'), 1e9));
        assert(csv.startsWith('id,big,price,'), 'Header is the first CSV line');
        assert(csv.includes(',"has, comma",'), 'Comma in a value is quoted');
        assert(csv.includes(',"say ""hi""\nbye",'), 'Quotes and newline are escaped');
        assert(csv.includes(',"[1,2]",'), 'Nested JSON with commas is quoted');
    }

    console.log('\n📋 Other codecs');
    for (const codec of ['gzip', 'brotli', 'lz4']) {
        const t = await readParquet(fixture(`codec.${codec}.parquet`), 1e9);
        assertEqual(t.rows, [['a'], ['b']], `${codec} decodes`);
    }

    console.log('\n📋 Large files read only leading row groups');
    {
        const all = await readParquet(fixture('rowgroups.parquet'), 1e9);
        assertEqual([all.rows.length, all.totalRows], [100, 100], 'Under the limit: all 4 row groups read');
        const some = await readParquet(fixture('rowgroups.parquet'), 1);
        assertEqual([some.rows.length, some.totalRows], [25, 100], 'Over the limit: at least the first row group, partial');
        assertEqual(some.rows[24], ['24'], 'Partial read ends at the row-group boundary');
    }

    console.log('\n📋 parquetValueToString');
    assertEqual(parquetValueToString(12345678901234567890n), '12345678901234567890', 'BigInt keeps full precision');
    assertEqual(parquetValueToString({ v: 12345678901234567890n }), '{"v":"12345678901234567890"}', 'Unsafe BigInt in JSON becomes a string');
    assertEqual(parquetValueToString(new Date(NaN)), '', 'Invalid date is empty, not a crash');
    assertEqual(parquetValueToString([new Uint8Array([0xff])]), '["<binary 1 bytes>"]', 'Nested binary uses the placeholder');
    assertEqual(parquetValueToString(null), '', 'null is an empty cell');

    console.log('\n📋 Errors');
    {
        let err = null;
        try { await readParquet(path.join(__dirname, '..', 'samples', 'valid_data.csv'), 1e9); } catch (e) { err = e; }
        assert(err instanceof Error && err.message.length > 0, `Non-Parquet file rejects with a message (${err && err.message})`);
    }

    console.log('\n📋 Wiring (source checks)');
    {
        const pkg = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
        const patterns = pkg.contributes.customEditors[0].selector.map(s => s.filenamePattern);
        assert(patterns.includes('*.parquet'), 'customEditors selector includes *.parquet');
        const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'csvEditor.ts'), 'utf8');
        assert(src.includes('readOnly: isBinary'), 'Parquet is sent to the webview as read-only');
        assert(/if \(isBinary\) \{\s*console\.warn\('CSV ClearView: edit ignored/.test(src), 'Host ignores edits to Parquet files');
    }

    // --------------------------------------------------------
    console.log('\n' + '='.repeat(50));
    console.log(`Results: ${passed} passed, ${failed} failed`);
    if (failed > 0) {
        console.log('\nFailed tests:');
        failures.forEach(f => console.log(`  ❌ ${f}`));
        process.exit(1);
    } else {
        console.log('All tests passed! ✅');
        process.exit(0);
    }
}

runTests().catch(e => {
    console.error('Test runner error:', e);
    process.exit(1);
});
